// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    // A recorder that implements the exact signature transferFrom(address,address,uint256)
    // and records calls so the test can observe that c made the external calls.
    RecordingTarget target;

    function setUp() public {
        c = new airPort();
        target = new RecordingTarget();
    }

    // Fuzz over: an address 'from' (as uint160), a single recipient address in the _tos array (as uint160), and a value v.
    // We keep domains wide; the helper records the call and returns success.
    function testFuzz_property(uint160 fromRaw, uint160 toRaw, uint256 v) public {
        address from = address(fromRaw);
        address to = address(toRaw);

        // prepare a single-element array of recipients
        address[] memory tos = new address[](1);
        tos[0] = address(target); // point to our recording target so the call is observable

        // Ensure tos.length > 0 (already true) and exercise arbitrary v.
        // Call transfer and capture the returned boolean via try/catch to observe success vs revert.
        bool ok;
        try c.transfer(from, address(target), tos, v) returns (bool ret) {
            ok = ret; // should be true on reference for all inputs where it doesn't revert
        } catch {
            // If it reverts, set ok = false; but reference only reverts if tos.length==0 which we ensured not
            ok = false;
        }

        // The universal property: for any admissible inputs (tos non-empty) the reference returns true for completed calls.
        // Therefore assertTrue(ok) will always hold on the reference but fail on the mutant (which returns false).
        assertTrue(ok);
    }
}

// Recording helper: exposes the exact signature transferFrom(address,address,uint256)
// so that abi.encodeWithSelector(...) from C decodes properly and the call is recorded.
contract RecordingTarget {
    event Recorded(address indexed from, address indexed to, uint256 value);
    // This function matches the selector C computes: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        emit Recorded(from, to, value);
        return true; // succeed so reference proceeds; mutant still returns false at the end
    }
}
